from mcp.server import fastmcp

# Sub-server with math tools
math_server = fastmcp.Server("math")

@math_server.tool()
def add(a: float, b: float) -> float:
    """Add two numbers."""
    return a + b

@math_server.tool()
def subtract(a: float, b: float) -> float:
    """Subtract two numbers."""
    return a - b

@math_server.tool()
def multiply(a: float, b: float) -> float:
    """Multiply two numbers."""
    return a * b

@math_server.tool()
def divide(a: float, b: float) -> float:
    """Divide two numbers."""
    if b == 0:
        raise ValueError("Cannot divide by zero")
    return a / b

# Main server
main_server = fastmcp.Server("main")

# Attach math server tools to main server with "math" prefix
for tool_name, tool_func in math_server.tools.items():
    def make_prefixed_tool(func, name):
        def prefixed(*args, **kwargs):
            return func(*args, **kwargs)
        prefixed.__name__ = f"math_{name}"
        prefixed.__doc__ = func.__doc__
        return prefixed

    main_server.tool()(make_prefixed_tool(tool_func, tool_name))

if __name__ == "__main__":
    main_server.run()

